        time.asctime(*((TIME_MINYEAR - 1,) + (0,) * 8,))
    except OverflowError:
        pass
    try:
        time.asctime(*(0,))
    except TypeError:
        pass
    try:
        time.asctime(*((),))
    except TypeError:
        pass
    try:
        time.asctime(*((0,) * 10,))
    except TypeError:
        pass
try:
    _t()
except BaseException as _e:
